private val logos = HashMap<Source, ImageVector>()

fun Source.logo(): ImageVector = logos.getOrPut(this) {
    val d = chemins[this] ?: return@getOrPut androidx.compose.material.icons.Icons.Outlined.Groups
    ImageVector.Builder(id, 24.dp, 24.dp, 24f, 24f)
        .addPath(PathParser().parsePathString(d).toNodes(), fill = SolidColor(Color.Black))
        .build()
}

/** Pastille ronde à la couleur de la messagerie, avec son logo. */
@Composable
fun LogoSource(s: Source, taille: Dp = 24.dp, modifier: Modifier = Modifier) {
    Box(modifier.size(taille).background(s.teinte(), CircleShape), contentAlignment = Alignment.Center) {
        Icon(s.logo(), s.libelle, tint = Color.White, modifier = Modifier.size(taille * 0.58f))
    }
}

/** Tracé SVG brut du logo (24 × 24), pour les dessins hors Compose (notification permanente). */
internal fun cheminLogo(s: Source): String? = chemins[s]
